    if (n <= 1) return 0;
    if (n <= 3) return 1;
    if (n % 2 == 0 || n % 3 == 0) return 0;
    unsigned int i = 5;
    while (i * i <= n) {
        if (n % i == 0 || n % (i + 2) == 0)
            return 0;
        i = i + 6;
    }
    return 1;
}

int main(void) {
    unsigned int n = __VERIFIER_nondet_uint();
    assume(n <= 1000);
    unsigned int i = 1;
    unsigned int total = 0;
    while (i <= n) {
        if(is_prime(i)) {
            total = total + i;
        }
        i++;
    }
    assert(total >= 0); // The sum of primes is non-negative
    return 0;
}

