int is_palindrome(unsigned int number) {
    unsigned int reversed = 0, original = number, remainder;
    while (number != 0) {
        remainder = number % 10;
        reversed = reversed * 10 + remainder;
        number /= 10;
    }
    return original == reversed;
}

